    let edits = requests
        .into_iter()
        .map(|request| request.edit)
        .collect::<Vec<_>>();
    let opts = system::edits::ApplyOpts {
        part: "mise-shell-activate",
        dry_run,
        verbose: Settings::get().verbose,
        yes,
    };
    system::edits::apply(config, &edits, &opts).map(|_| ())
}

