                    name,
                    version,
                    tap_url,
                    desired: package.desired(),
                });
            }
            Err(err) => warn!("[bootstrap.packages]: {err}"),
        }
    }
    #[cfg(unix)]
    let options = if cask_adopt.is_empty() {
        IndexMap::new()
    } else {
        IndexMap::from([(
            "brew-cask".to_string(),
            ManagerPackageOptions::BrewCask { adopt: cask_adopt },
        )])
    };
    #[cfg(not(unix))]
    let options = IndexMap::new();
    (by_mgr, options)
