}

fn desired_package(request: &super::packages::PackageRequest) -> String {
    if request.desired == super::packages::PackageDesiredState::Absent {
        return "absent".to_string();
    }
    request
        .version
        .as_ref()
        .map(|version| format!("installed ({version})"))
        .unwrap_or_else(|| "installed (any version)".to_string())
}

fn package_resource_state(
    state: PackageState,
    request: &PackageRequest,
    supports_version_pins: bool,
    supports_remove: bool,
) -> (String, ResourceAction) {
    if request.desired == super::packages::PackageDesiredState::Absent {
        return match state {
            PackageState::Missing => ("absent".to_string(), ResourceAction::Noop),
            #[cfg(unix)]
            PackageState::Unavailable { reason } => {
                (format!("skipped ({reason})"), ResourceAction::Unknown)
            }
            PackageState::Installed { version }
            | PackageState::NeedsRepair { installed: version }
            | PackageState::VersionMismatch { installed: version } => (
                format!("installed ({version})"),
                if supports_remove {
                    ResourceAction::Remove
                } else {
                    ResourceAction::Unknown
                },
            ),
            #[cfg(unix)]
            PackageState::InstalledAutoUpdates { version } => (
                format!("installed ({version})"),
                if supports_remove {
                    ResourceAction::Remove
                } else {
                    ResourceAction::Unknown
                },
            ),
        };
    }
    let unsupported_pin = request.version.is_some() && !supports_version_pins;
    match state {
        PackageState::Installed { version } => {
            (format!("installed ({version})"), ResourceAction::Noop)
        }
        #[cfg(unix)]
            copy.host = base.join(&copy.host);
        }
    }
}

/// Convenience wrapper that merges `[oci]` across *all* loaded configs.
/// Used when the caller has explicitly opted into global/system scope.
pub(super) fn merged_oci_config(config: &Config) -> OciConfig {
    merged_oci_config_from(config.config_files.values())
}

/// Load config + toolset, merge the `[oci]` section, and build the image.
/// Used by `mise oci build`, `mise oci run`, and `mise oci push`.
///
/// By default both the toolset and the `[oci]` section are scoped to configs
/// at-or-below the project root — i.e. the user's global config, system
/// config, and parent-directory configs above the project (e.g. a `~/mise.toml`
/// setting personal Node defaults) are excluded. Rationale: `mise oci build`
/// is conceptually "package *this project's* tools into a deployable image" —
/// personal dev tools (neovim, ripgrep, …) sitting in
/// `~/.config/mise/config.toml` have no business in a project image, and
/// several of them (asdf/vfox plugins) would in fact be rejected by the v1
/// builder. See discussion #9690.
///
/// Set `include_global = true` to revert to the merge-everything behavior.
pub(super) async fn perform_build(opts: BuildOptions, include_global: bool) -> Result<BuildOutput> {
    let config = Config::get().await?;
    if include_global {
        let ts = ToolsetBuilder::new().build(&config).await?;
        let oci = merged_oci_config(&config);
        reject_unsupported_system_defaults(&config.config_files)?;
        let files = system::files::files_from_config_files(&config.config_files);
        let packages = system::packages_from_config_files(&config.config_files);
        return Builder::new(config.clone(), ts, oci, opts)
            .with_dotfiles(files)
            .with_system_packages(packages)
            .build()
            .await;
    }
    let project_files = project_config_files(&config)?;
    let ts = build_project_toolset(&config, project_files.clone()).await?;
    let oci = merged_oci_config_from(project_files.values());
    reject_unsupported_system_defaults(&project_files)?;
    let files = system::files::files_from_config_files(&project_files);
    let packages = system::packages_from_config_files(&project_files);
    Builder::new(config.clone(), ts, oci, opts)
        .with_dotfiles(files)
        .with_system_packages(packages)
        .build()
        .await
}

/// Configs at-or-below the project root.
///
/// `cf.project_root().is_some()` is the right scope: it's None for the global
/// config, the system config, and parent-dir configs that live directly under
/// $HOME (e.g. `~/mise.toml` someone uses to set their default Node). It's
/// Some for any project config, including those walked up from CWD into a
/// monorepo root — which we *do* want included (sub-project + monorepo root
/// share the toolset of the deployable).
fn project_config_files(config: &Config) -> Result<ConfigMap> {
    let project_files: ConfigMap = config
        .config_files
        .iter()
        .filter(|(_, cf)| cf.project_root().is_some())
        .map(|(p, cf)| (p.clone(), cf.clone()))
        .collect();
    if project_files.is_empty() {
        bail!(
            "mise oci: no project mise config found in the current directory or any parent. \
             Add a `mise.toml` to the project, or pass `--include-global` to use tools and \
             [oci] settings from your global config (note: asdf/vfox plugins remain \
             unsupported)."
        );
    }
    Ok(project_files)
            bail!(
                "brew-cask is not available: {}",
                manager.unavailable_reason()
            );
        }
        let config = Config::get().await?;
        let configured = system::packages_from_config_and_tracked_config_files(&config)
            .await?
            .into_iter()
            .find(|mp| mp.manager.name() == "brew-cask")
            .map(|mp| mp.requests)
            .unwrap_or_default();
        let plan = brew::cask_prune_plan(&configured).await?;
        for skipped in &plan.skipped {
            warn!("brew-cask:{}: skipped: {}", skipped.token, skipped.reason);
        }
        if plan.is_empty() {
            info!("brew-cask: nothing to prune");
            return Ok(());
        }
        if self.dry_run {
            brew::apply_cask_prune_plan(&plan, true)?;
            return Ok(());
        }
        let remove = plan
            .remove
            .iter()
            .map(|candidate| format!("{}@{}", candidate.token, candidate.version))
            .collect::<Vec<_>>();
        if !self.yes && !Settings::get().yes && console::user_attended_stderr() {
            let msg = format!("brew-cask: prune {}?", remove.join(", "));
            if !prompt::confirm(msg)?.is_yes() {
                info!("brew-cask: skipped");
                return Ok(());
            }
        }
        let removed = brew::apply_cask_prune_plan(&plan, false)?;
        info!("brew-cask: pruned {removed} casks");
        Ok(())
    }

    #[cfg(not(unix))]
    async fn run_brew(self) -> Result<()> {
        let _ = self.manager;
        bail!("brew prune is not supported on windows")
    }

    #[cfg(not(unix))]
    async fn run_brew_cask(self) -> Result<()> {
        let _ = self.manager;
        bail!("brew-cask prune is not supported on windows")
    }
}

