 704	    }
 705	    let unsupported_pin = request.version.is_some() && !supports_version_pins;
 706	    match state {
 707	        PackageState::Installed { version } => {
 708	            (format!("installed ({version})"), ResourceAction::Noop)
 709	        }
 710	        #[cfg(unix)]
 711	        PackageState::InstalledAutoUpdates { version } => {
 712	            (format!("installed ({version})"), ResourceAction::Noop)
 713	        }
 714	        PackageState::Missing if unsupported_pin => (
 715	            "missing (manager cannot install pinned versions)".to_string(),
 716	            ResourceAction::Unknown,
 717	        ),
 718	        PackageState::Missing => ("missing".to_string(), ResourceAction::Create),
 719	        PackageState::NeedsRepair { installed } => (
 720	            format!("{installed} (needs repair)"),
