 671	fn package_resource_state(
 672	    state: PackageState,
 673	    request: &PackageRequest,
 674	    supports_version_pins: bool,
 675	    supports_remove: bool,
 676	) -> (String, ResourceAction) {
 677	    if request.desired == super::packages::PackageDesiredState::Absent {
 678	        return match state {
 679	            PackageState::Missing => ("absent".to_string(), ResourceAction::Noop),
 680	            #[cfg(unix)]
 681	            PackageState::Unavailable { reason } => {
 682	                (format!("skipped ({reason})"), ResourceAction::Unknown)
 683	            }
 684	            PackageState::Installed { version }
 685	            | PackageState::NeedsRepair { installed: version }
 686	            | PackageState::VersionMismatch { installed: version } => (
 687	                format!("installed ({version})"),
 688	                if supports_remove {
 689	                    ResourceAction::Remove
 690	                } else {
 691	                    ResourceAction::Unknown
 692	                },
 693	            ),
 694	            #[cfg(unix)]
 695	            PackageState::InstalledAutoUpdates { version } => (
 696	                format!("installed ({version})"),
 697	                if supports_remove {
 698	                    ResourceAction::Remove
 699	                } else {
 700	                    ResourceAction::Unknown
 701	                },
 702	            ),
 703	        };
 704	    }
 705	    let unsupported_pin = request.version.is_some() && !supports_version_pins;
 706	    match state {
 707	        PackageState::Installed { version } => {
 708	            (format!("installed ({version})"), ResourceAction::Noop)
 709	        }
 710	        #[cfg(unix)]
 711	        PackageState::InstalledAutoUpdates { version } => {
 712	            (format!("installed ({version})"), ResourceAction::Noop)
 713	        }
 714	        PackageState::Missing if unsupported_pin => (
 715	            "missing (manager cannot install pinned versions)".to_string(),
 716	            ResourceAction::Unknown,
 717	        ),
 718	        PackageState::Missing => ("missing".to_string(), ResourceAction::Create),
 719	        PackageState::NeedsRepair { installed } => (
 720	            format!("{installed} (needs repair)"),
 220	            .collect::<Vec<_>>()
