fn unpack_base_layers(layout: &ImageLayout, layers: &[Descriptor], rootfs: &Path) -> Result<()> {
    for layer in layers {
        let path = layout.blob_path(&layer.digest);
        let reader = open_layer_reader(layer, &path)?;
        let mut archive = Archive::new(reader);
        let mut options = UnpackOptions::default();
        let mut unpacker = EntryUnpacker::new(rootfs, &mut options)
            .wrap_err_with(|| format!("preparing base layer extraction {}", layer.digest))?;
        for entry in archive
            .entries()
            .wrap_err_with(|| format!("reading base layer {}", layer.digest))?
        {
            let mut entry =
                entry.wrap_err_with(|| format!("reading base layer entry {}", layer.digest))?;
            let rel = clean_layer_path(&entry.path()?)
                .wrap_err_with(|| format!("reading base layer entry path {}", layer.digest))?;
            if rel.as_os_str().is_empty() || apply_oci_whiteout(rootfs, &rel)? {
                continue;
            }
            unpacker
                .unpack(&mut entry)
                .wrap_err_with(|| format!("unpacking base layer {}", layer.digest))?;
        }
        unpacker
            .finish()
            .wrap_err_with(|| format!("finishing base layer extraction {}", layer.digest))?;
    }
    Ok(())
}

fn open_layer_reader(layer: &Descriptor, path: &Path) -> Result<Box<dyn Read>> {
    let file =
        fs::File::open(path).wrap_err_with(|| format!("opening base layer {}", path.display()))?;
    let mut reader = BufReader::new(file);
    Ok(match layer_compression(layer, &mut reader)? {
        LayerCompression::Gzip => Box::new(GzDecoder::new(reader)),
        LayerCompression::Zstd => Box::new(zstd::stream::read::Decoder::new(reader)?),
        LayerCompression::Tar => Box::new(reader),
    })
}

enum LayerCompression {
    Gzip,
    Zstd,
    Tar,
}

fn layer_compression<R: BufRead>(layer: &Descriptor, reader: &mut R) -> Result<LayerCompression> {
    }
}

/// Split a `"manager:package"` spec (config key or CLI argument). Only the
/// first `:` separates — apt arch qualifiers ("apt:gcc:arm64") and brew
/// versioned formula names ("brew:postgresql@17") stay part of the package.
pub(crate) fn parse_spec(spec: &str) -> eyre::Result<(String, String)> {
    match spec.split_once(':') {
        Some((mgr, pkg)) if !mgr.is_empty() && !pkg.is_empty() => {
            Ok((mgr.to_string(), pkg.to_string()))
        }
        _ => bail!(
            "invalid system package spec '{spec}': expected '<manager>:<package>' (e.g. \"apt:curl\")"
        ),
    }
}

/// Split a `mise bootstrap packages use` spec `manager:package[@version]` into its parts.
///
/// `@version` mirrors `mise use tool@version`; `@latest` (or no `@`) means no
/// pin. brew and brew-cask are exempt from `@` parsing: `@` is part of
/// Homebrew names (`postgresql@17` — that name IS brew's versioning
/// mechanism), and bottles/casks can't be installed at a pinned version
/// anyway. mas uses numeric ADAM IDs only.
pub(crate) fn parse_use_spec(spec: &str) -> eyre::Result<(String, PackageRequest)> {
    let (mgr, rest) = parse_spec(spec)?;
    let rest = normalize_use_spec_package_name(&mgr, &rest)?;
    validate_package_name(&mgr, rest)?;
    if is_opaque_package_manager(&mgr) {
        return Ok((
            mgr,
            PackageRequest {
                name: rest.to_string(),
                version: None,
                tap_url: None,
                desired: packages::PackageDesiredState::Present,
            },
        ));
    }
    match rest.rsplit_once('@') {
        Some((name, version)) if !name.is_empty() && !version.is_empty() => Ok((
            mgr,
            PackageRequest {
                name: name.to_string(),
                version: (version != "latest").then(|| version.to_string()),
                tap_url: None,
                desired: packages::PackageDesiredState::Present,
            },
        )),
        Some(_) => {
            bail!("invalid system package spec '{spec}': expected '<manager>:<package>[@version]'")
        }
        None => Ok((
            mgr,
            PackageRequest {
                name: rest.to_string(),
                version: None,
                tap_url: None,
                desired: packages::PackageDesiredState::Present,
            },
        )),
    }
}

