}

pub(crate) fn attach_brew_tap_urls(
    config: &Config,
    by_mgr: &mut IndexMap<String, Vec<PackageRequest>>,
        let pacman = packages_from_config_files(&config_files)
            .into_iter()
            .find(|packages| packages.manager.name() == "pacman")
            .unwrap();

        assert_eq!(pacman.requests.len(), 1);
        assert_eq!(
            pacman.requests[0].desired,
            packages::PackageDesiredState::Absent
        );
        assert_eq!(pacman.requests[0].version, None);
        Ok(())
    }

    #[cfg(unix)]
    #[test]
    fn test_package_configs_preserve_inherited_selectors() -> Result<()> {
        let (_dir, config_files) = config_map_from_toml(&[
            (
                "local.toml",
                r#"
                    [bootstrap.packages]
                    "brew:jq" = "latest"
                    "brew-cask:1password" = { version = "latest", os = ["linux"] }
                "#,
            ),
            (
                "global.toml",
                r#"
                    [bootstrap.packages]
                    "brew-cask:1password" = { version = "latest", os = ["macos"] }
                "#,
            ),
        ])?;

        let local_path = config_files.get_index(0).unwrap().0.clone();
        let global_path = config_files.get_index(1).unwrap().0.clone();

        let packages = package_configs_from_config_files_for_target(&config_files, &local_path);
        assert!(matches!(
            packages.get("brew-cask:1password"),
            Some(PackageTomlConfig::Options(options)) if options.os == ["linux"]
        ));

        let global_packages =
            package_configs_from_config_files_for_target(&config_files, &global_path);
        assert!(matches!(
            global_packages.get("brew-cask:1password"),
            Some(PackageTomlConfig::Options(options)) if options.os == ["macos"]
        ));
        assert!(!global_packages.contains_key("brew:jq"));
        Ok(())
    }

    #[cfg(unix)]
    #[test]
    fn test_brew_cask_adopt_option_reaches_package_request() -> Result<()> {
        let (_dir, config_files) = config_map_from_toml(&[(
            "mise.toml",
            r#"
                [bootstrap.brew]
                adopt = true

                [bootstrap.packages]
                "brew-cask:textmate" = "latest"
                "brew-cask:replace-me" = { adopt = false }
            "#,
        )])?;

        let packages = packages_from_config_files(&config_files);
        let casks = packages
            .into_iter()
            .find(|packages| packages.manager.name() == "brew-cask")
            .unwrap();
        assert_eq!(casks.requests.len(), 2);
        assert!(casks.options.brew_cask_adopt("textmate"));
        assert!(!casks.options.brew_cask_adopt("replace-me"));
        Ok(())
    }

